/**
 * NATURE DE L'INSTRUMENT — et ce qu'on a le droit d'en conclure.
 *
 * Deriv indique sur sa page officielle que ses indices synthétiques sont
 * « generated by a cryptographically secure random number generator ». Sur une
 * marche aléatoire issue d'un tel générateur, aucune méthode chartiste ne peut
 * avoir d'avantage : il n'y a ni information, ni acteur qui réagisse à un niveau.
 *
 * Un backtest positif sur R_75 ne mesure donc pas une compétence. Il mesure un
 * bug, une fuite dans le rejeu, ou du bruit. Le système doit le dire à l'écran au
 * lieu de laisser croire que +0,28 R sur le décile est un résultat.
 *
 * On ne classe comme synthétiques que les séries non ambiguës. Les indices `OTC_*`
 * sont laissés hors du drapeau : leur construction n'est pas vérifiée ici, et
 * marquer à tort un instrument réel serait aussi fautif que l'inverse.
 */

const SYNTHETIQUES = [
  /^R_\d+$/,            // R_10, R_25, R_50, R_75, R_100 (indices de volatilité)
  /^1HZ\d+V$/i,         // 1HZ100V… (volatilité à la seconde)
  /^(BOOM|CRASH)\d+$/i, // Boom / Crash (RNG avec sauts programmés)
  /^JD\d+$/i,           // Jump indices
  /^stpRNG/i            // step index
];

/** Vrai si le symbole est une série générée par un RNG, pas un marché. */
function synthetique(symbol) {
  const s = String(symbol || '').trim();
  if (!s) return false;
  return SYNTHETIQUES.some(re => re.test(s));
}

/** Avertissement à afficher, ou null si l'instrument est un vrai marché. */
function avertissement(symbol) {
  if (!synthetique(symbol)) return null;
  return `${symbol} est un indice synthétique, produit par un générateur `
    + `aléatoire cryptographique. Aucun avantage statistique ne peut y exister par `
    + `construction : un résultat positif ici ne valide pas la méthode. `
    + `Conclure sur un marché réel (XAUUSD, forex, crypto).`;
}

module.exports = { synthetique, avertissement, SYNTHETIQUES };
